#include "stdafx.h"#include "Queue.h"#include "..\Lang.h"////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структураtypedef struct : public SPROLOZ  {  POINT pt;  int h,w;  enum EDirect eDir;  } Queue_Arrow;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void PntArrow(HDC hDC, EDirect eDir, int x, int y, int n9, int n3 )  {  ::BeginPath(hDC);  ::MoveToEx( hDC, x, y,NULL );  switch ( eDir )    {    case dirUp:      ::LineTo  ( hDC, x+n3, y+n9 );      ::LineTo  ( hDC, x-n3, y+n9 );    break;    case dirDown:      ::LineTo  ( hDC, x+n3, y-n9 );      ::LineTo  ( hDC, x-n3, y-n9 );    break;    case dirLeft:      ::LineTo  ( hDC, x+n9, y+n3 );      ::LineTo  ( hDC, x+n9, y-n3 );    break;    case dirRight:      ::LineTo  ( hDC, x-n9, y+n3 );      ::LineTo  ( hDC, x-n9, y-n3 );    break;    }  ::EndPath(hDC);  ::StrokeAndFillPath(hDC);  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintArrow(DefinePaint)  {  QueueP(Queue_Arrow);  PntArrow( hDC, p->eDir,p->pt.x, p->pt.y, p->h, p->w );  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddArrow(DefineTegs)  {  AddQueueEx(Queue_Arrow);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintArrow;  //  p->h =10;  p->w = 4;  //  STegObj obj[] =    {    { 'P', "pt"    , &p->pt   },    { 'I', "x"     , &p->pt.x },    { 'I', "y"     , &p->pt.y },    { 'I', "height", &p->h    },    { 'I', "width" , &p->w    },    { 'I', "h"     , &p->h    },    { 'I', "w"     , &p->w    },    };  //  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  p->eDir = ParserDirect(teg[0].value);  //  switch ( p->eDir )    {    case dirUp:     ::SetRect(&p->mRect,p->pt.x-p->w,p->pt.y,p->pt.x+p->w,p->pt.y+p->h);    break;    case dirDown:     ::SetRect(&p->mRect,p->pt.x-p->w,p->pt.y-p->h,p->pt.x+p->w,p->pt.y);    break;    case dirLeft:     ::SetRect(&p->mRect,p->pt.x,p->pt.y-p->w,p->pt.x+p->h,p->pt.y+p->w);    break;    case dirRight:     ::SetRect(&p->mRect,p->pt.x-p->h,p->pt.y-p->w,p->pt.x,p->pt.y+p->w);    break;    }  //  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~